+pub struct SessionProjectionFrame {
+    pub cursor: String,
+    pub source: SessionProjectionSource,
+    pub event: Value,
+}
+
+/// Authoritative folded replacements not fully represented by provider history.
+/// After hydrating session content and reducing `pending_events`, clients install
+/// every field here as the final active/terminal/reroute/permission/browser
+/// value. Components are intentionally absent: reconstruct their canonical
+/// registry by scanning checkpoint/session tool context in order and applying a
+/// `component_render`/`component_unmount` call only after a later successful
+/// (`is_error == false`) result with the same `tool_call_id`. Failed, missing,
+/// or result-before-call pairs have no component effect. Then reduce component
+/// frames after the checkpoint. Folded fields are not reducer inputs.
