+    #[serde(default, skip_serializing_if = "Option::is_none")]
+    pub active_turn: Option<Value>,
+    #[serde(default, skip_serializing_if = "Option::is_none")]
+    pub last_turn_finished: Option<Value>,
+    #[serde(default, skip_serializing_if = "Option::is_none")]
+    pub model_rerouted: Option<Value>,
+    #[serde(default)]
+    pub pending_permissions: Vec<Value>,
+    #[serde(default)]
+    pub browser_active: bool,
+}
+
+/// Typed durable transcript/tool replacement carried by checkpoint frames.
+#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
+#[serde(tag = "type", deny_unknown_fields)]
+pub enum SessionProjectionCheckpoint {
+    /// Inline normalized replacement. Clients replace transcript/tool context
+    /// and reconstruct components by scanning tool context in order: retain a
+    /// component render/unmount call until a later result with the same call id,
+    /// apply it only when that result has `is_error == false`, and discard it on
+    /// failed or missing result. Raw provider messages and image/base64 bytes are
+    /// deliberately absent.
+    #[serde(rename = "projection_checkpoint")]
+    Inline {
+        persistence_revision: u64,
+        transcript: Vec<SessionTranscriptEntry>,
+        tool_context: Vec<SessionToolContext>,
+    },
+    /// The exact replacement exceeded the journal's inline bound. A live-tail
+    /// client must stop and refetch the canonical session snapshot. On the fresh
+    /// GET that follows, canonical `session` content already satisfies this
+    /// marker, so it is not recursively refetched.
+    #[serde(rename = "projection_checkpoint_refetch")]
+    Refetch { persistence_revision: u64 },
+}
