+        match self {
+            Self::Inline {
+                persistence_revision,
+                ..
+            }
+            | Self::Refetch {
+                persistence_revision,
+            } => *persistence_revision,
+        }
+    }
+
+    pub fn requires_refetch(&self) -> bool {
+        matches!(self, Self::Refetch { .. })
+    }
+}
