+        assert!(response.projection.is_none());
+    }
+
+    #[test]
+    fn transcript_blocks_are_additive_and_preserve_completed_thinking_type() {
+        let legacy: SessionTranscriptEntry = serde_json::from_value(serde_json::json!({
+            "role":"assistant", "text":"legacy flattened"
+        }))
+        .unwrap();
+        assert!(legacy.blocks.is_empty());
+
+        let exact: SessionTranscriptEntry = serde_json::from_value(serde_json::json!({
+            "role":"assistant",
+            "text":"reasonanswer",
+            "blocks":[
+                {"type":"thinking", "thinking":"reason"},
+                {"type":"text", "text":"answer"}
+            ]
+        }))
+        .unwrap();
+        assert_eq!(
+            exact.blocks,
+            vec![
+                SessionTranscriptBlock::Thinking {
+                    thinking: "reason".into()
+                },
+                SessionTranscriptBlock::Text {
+                    text: "answer".into()
+                }
+            ]
+        );
+    }
+
+    #[test]
+    fn projection_checkpoint_inline_and_refetch_markers_are_typed() {
+        let inline: SessionProjectionCheckpoint = serde_json::from_value(serde_json::json!({
+            "type":"projection_checkpoint",
+            "persistence_revision":4,
+            "transcript":[{"role":"user","text":"durable"}],
+            "tool_context":[],
+        }))
+        .unwrap();
+        assert_eq!(inline.persistence_revision(), 4);
+        assert!(!inline.requires_refetch());
+        let marker: SessionProjectionCheckpoint = serde_json::from_value(serde_json::json!({
+            "type":"projection_checkpoint_refetch",
+            "persistence_revision":5,
+        }))
+        .unwrap();
+        assert_eq!(marker.persistence_revision(), 5);
+        assert!(marker.requires_refetch());
+    }
+
