+        let projection: SessionProjection = serde_json::from_value(serde_json::json!({
+            "version":1,
+            "cursor":"sp1:00000000-0000-0000-0000-000000000000:0123456789abcdef:3",
+            "checkpoint_revision":1,
+            "checkpoint":{
+                "type":"projection_checkpoint",
+                "persistence_revision":1,
+                "transcript":[{"role":"user","text":"base"}],
+                "tool_context":[]
+            },
+            "lease_id":"00000000-0000-0000-0000-000000000001",
+            "lease_expires_ms":99,
+            "pending_events":[
+                {"cursor":"sp1:00000000-0000-0000-0000-000000000000:0123456789abcdef:1","source":"agent","event":{"type":"assistant_text_delta","delta":"tail"}},
+                {"cursor":"sp1:00000000-0000-0000-0000-000000000000:0123456789abcdef:2","source":"agent","event":{"type":"component_render","component_id":"card","kind":"markdown","props":{}}},
+                {"cursor":"sp1:00000000-0000-0000-0000-000000000000:0123456789abcdef:3","source":"agent","event":{"type":"turn_started","turn_id":"t"}}
+            ],
+            "state":{
+                "active_turn":{"type":"turn_started","turn_id":"t","authoritative":true},
+                "pending_permissions":[],
+                "browser_active":false
+            }
+        }))
+        .unwrap();
+        assert!(matches!(
+            projection.checkpoint,
+            Some(SessionProjectionCheckpoint::Inline { .. })
+        ));
+        let content_inputs = projection
+            .pending_events
+            .iter()
+            .filter(|frame| {
+                frame.source == SessionProjectionSource::Checkpoint
+                    || matches!(
+                        frame.event["type"].as_str(),
+                        Some("assistant_text_delta" | "component_render" | "component_unmount")
+                    )
+            })
+            .count();
+        assert_eq!(content_inputs, 2);
+        assert!(serde_json::to_value(&projection.state)
+            .unwrap()
+            .get("components")
+            .is_none());
+        assert_eq!(
+            projection.state.active_turn.as_ref().unwrap()["authoritative"],
+            true
+        );
+    }
