    #[test]
    fn cursors_are_session_scoped_contiguous_and_surface_patch_is_excluded() {
        let store = store(DEFAULT_LEASE);
        let a = AgentSessionId::new_v4();
        let b = AgentSessionId::new_v4();
        let turn = AgentTurnId::new_v4();
        let attached = attach(&store, &a.to_string(), 0);
        let first = store
            .append_agent(&AgentTurnEvent::AssistantTextDelta {
                session_id: a,
                turn_id: turn,
                delta: "a".into(),
            })
            .unwrap()
            .unwrap();
        let second = store
            .append_agent(&AgentTurnEvent::AssistantTextDelta {
                session_id: a,
                turn_id: turn,
                delta: "b".into(),
            })
            .unwrap()
            .unwrap();
        let other = store
            .append_agent(&AgentTurnEvent::AssistantTextDelta {
                session_id: b,
                turn_id: turn,
                delta: "x".into(),
            })
            .unwrap()
            .unwrap();
        assert_eq!(first.seq, 2);
