    fn checkpoint_value(revision: u64) -> Value {
        serde_json::json!({
            "type": "projection_checkpoint",
            "persistence_revision": revision,
            "transcript": [],
            "tool_context": [],
        })
    }

    fn attach(
        store: &SessionProjectionStore,
        session_id: &str,
        revision: u64,
    ) -> SessionProjection {
        store
            .snapshot(session_id, revision, checkpoint_value(revision))
            .unwrap()
    }

    /// Contract fixture only: clients, not the daemon store, reconstruct the
    /// canonical component registry. A component call takes effect only when a
    /// later same-call-id result is explicitly successful (`is_error == false`).
    fn reconstruct_components(
        tool_context: &[ocean_core::SessionToolContext],
    ) -> BTreeMap<String, Value> {
        let mut pending = HashMap::<String, &ocean_core::SessionToolContext>::new();
        let mut components = BTreeMap::new();
        for entry in tool_context {
            match entry.kind.as_str() {
                "call"
                    if matches!(
                        entry.tool_name.as_str(),
                        "component_render" | "component_unmount"
                    ) =>
                {
                    pending.insert(entry.tool_call_id.clone(), entry);
                }
                "result" => {
                    let Some(call) = pending.remove(&entry.tool_call_id) else {
                        continue;
                    };
                    if entry.is_error != Some(false) {
                        continue;
                    }
                    let Some(arguments) = call.arguments.as_ref() else {
                        continue;
                    };
                    let Some(id) = arguments.get("id").and_then(Value::as_str) else {
                        continue;
                    };
                    if call.tool_name == "component_render" {
                        components.insert(id.to_string(), arguments.clone());
                    } else {
                        components.remove(id);
                    }
                }
                _ => {}
            }
        }
        components
    }

