            })
            .unwrap();
        store
            .append_agent(&AgentTurnEvent::ComponentUnmount {
                session_id: session,
                component_id: "card".into(),
            })
            .unwrap();
        store
            .append_agent(&AgentTurnEvent::BrowserActivity {
                session_id: session,
                active: true,
            })
