    #[test]
    fn partial_page_disconnect_only_acknowledges_reconnect_cursor() {
        let dir = tempdir().unwrap();
        let store = SessionProjectionStore::open_with_config(
            &dir.path().join("projection.db"),
            1,
            DEFAULT_LEASE,
        )
        .unwrap();
        let session = AgentSessionId::new_v4();
        let turn = AgentTurnId::new_v4();
        let attached = attach(&store, &session.to_string(), 0);
        store
            .begin_tail_request(&session.to_string(), &attached.cursor, &attached.lease_id)
            .unwrap();
        for index in 0..270 {
            store
                .append_agent(&AgentTurnEvent::AssistantTextDelta {
                    session_id: session,
                    turn_id: turn,
                    delta: format!("row-{index}"),
                })
                .unwrap();
        }
        let fetched = store
            .page_after(&session.to_string(), &attached.cursor, &attached.lease_id)
            .unwrap();
        assert_eq!(fetched.len(), PAGE_LIMIT);
        let fetched_tail = ProjectionCursor::parse(&fetched.last().unwrap().cursor)
            .unwrap()
            .seq;
        let lease_min = store
            .leases
            .lock()
            .unwrap()
            .get(&attached.lease_id)
            .unwrap()
            .min_seq;
        assert_eq!(
            lease_min,
            ProjectionCursor::parse(&attached.cursor).unwrap().seq
        );
        assert!(fetched_tail > lease_min);

        store
            .checkpoint(&session.to_string(), 1, checkpoint_value(1))
            .unwrap();
        store.compact(true).unwrap();
        let received_cursor = fetched[9].cursor.clone();
        store
            .begin_tail_request(&session.to_string(), &received_cursor, &attached.lease_id)
            .unwrap();
        store.compact(true).unwrap();
        let replay = store
            .page_after(&session.to_string(), &received_cursor, &attached.lease_id)
            .unwrap();
        assert_eq!(replay.first().unwrap().event["delta"], "row-10");
        assert!(replay
            .iter()
            .any(|frame| frame.cursor == fetched.last().unwrap().cursor));
    }

