            SessionProjectionCheckpoint::Refetch {
                persistence_revision: 1
            }
        );

        let fresh = store.snapshot(&session, 1, oversized).unwrap();
        assert_eq!(fresh.checkpoint, Some(marker));
        assert!(fresh.pending_events.is_empty());
        store
            .begin_tail_request(&session, &fresh.cursor, &fresh.lease_id)
            .unwrap();
        assert!(store
            .page_after(&session, &fresh.cursor, &fresh.lease_id)
            .unwrap()
            .is_empty());
        assert!(!store.is_faulted(&session));
    }

    #[test]
    fn checkpoint_rejects_non_normalized_payload() {
        let store = store(DEFAULT_LEASE);
        let session = AgentSessionId::new_v4().to_string();
        let error = store
            .checkpoint(
                &session,
                1,
                serde_json::json!({
                    "type":"projection_checkpoint",
                    "persistence_revision":1,
                    "transcript":[],
                    "tool_context":[],
                    "messages":[{"image":"base64"}],
                }),
            )
            .unwrap_err();
        assert!(error.to_string().contains("not normalized"));
    }

    #[test]
    fn checkpoint_compacts_only_committed_rows_after_lease_expiry() {
        let store = store(Duration::ZERO);
        let session = AgentSessionId::new_v4();
        let turn = AgentTurnId::new_v4();
        store
            .append_agent(&AgentTurnEvent::AssistantTextDelta {
                session_id: session,
                turn_id: turn,
                delta: "done".into(),
            })
            .unwrap();
        store
            .checkpoint(&session.to_string(), 1, checkpoint_value(1))
            .unwrap();
        store.compact(false).unwrap();
        let snapshot = attach(&store, &session.to_string(), 1);
        assert!(snapshot.pending_events.is_empty());
        let old = ProjectionCursor::new(&store.epoch, &session.to_string(), 0).to_string();
        assert_eq!(
            store
                .page_after(&session.to_string(), &old, &snapshot.lease_id)
                .unwrap_err(),
            ProjectionReset::ExpiredLease
        );
    }
}

