+    event: Event,
+) -> bool {
+    tokio::select! {
+        biased;
+        _ = shutdown.cancelled() => false,
+        _ = tx.closed() => false,
+        _ = tokio::time::sleep_until(deadline) => false,
+        result = tx.send(Ok(event)) => result.is_ok(),
