+
+fn projection_request_cursor(
+    headers: &HeaderMap,
+    query_cursor: &str,
+) -> Result<String, session_projection::ProjectionReset> {
+    match headers.get("last-event-id") {
+        None => Ok(query_cursor.to_string()),
+        Some(value) => {
+            let cursor = value
+                .to_str()
+                .map_err(|_| session_projection::ProjectionReset::Malformed)?;
+            if cursor.is_empty() {
+                Err(session_projection::ProjectionReset::Malformed)
+            } else {
+                Ok(cursor.to_string())
+            }
+        }
+    }
+}
